function PVPArenaReplayDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type Engine.UI.UIArgument
        local argument          = self.controller.Argument
        local parameters        = argument.parameters
        local oneMatchChartData = parameters.oneMatchChartData
        local data              = parameters.data
        self.oneMatchChartData  = oneMatchChartData
        self:SetBattleRecord(data.records)

        PVPArenaUtils.RefreshCommonUITitleNode(self.CommonUITitleNode.gameObject, localize("战斗回放"))
        self:RefreshUI(oneMatchChartData)
        self:RefreshTeamGroups(self:InitTeamInfo(table.deserialize(data.teamInfo)))

    end))
    return coWait
end

