function PVPArenaReplayDialog:InitTeamInfo(teamInfo)
    local oneMatchChartData = self.oneMatchChartData
    local rightPlayerId     = oneMatchChartData.rightPlayerId
    local teams             = {}

    local teamNumber        = pvpArenaComponent:GetTeamNumbers()
    for i = 1, teamNumber do
        local teamData = teamInfo[i]
        if teamData and next(teamData) then
            local winPlayerId  = checkNumber(teamData.winPlayerId)

            local isLeftWin = true
            local leftCombat, rightCombat = checkNumber(teamData.winCombat), checkNumber(teamData.loseCombat)
            local leftCards, rightCards = checkTable(teamData.winCards), checkTable(teamData.loseCards)

            if winPlayerId == rightPlayerId then
                leftCombat, rightCombat = rightCombat, leftCombat
                leftCards, rightCards = rightCards, leftCards
                isLeftWin = false
            end
            local team = {
                combatValue = leftCombat,
                cards = leftCards,
                win = isLeftWin,
            }
            table.insert(teams, team)

            team = {
                combatValue = rightCombat,
                cards = rightCards,
                win = not isLeftWin,
            }
            table.insert(teams, team)
        else
            table.insert(teams, {})
            table.insert(teams, {})
        end
    end

    return teams
end

