function PVPArenaReplayDialog:RefreshUI(oneMatchChartData)
    self:RefreshTitleGroup(oneMatchChartData)
end

function PVPArenaReplayDialog:RefreshTitleGroup(oneMatchChartData)
    ---@type PVPArenaReplayTitleGroup
    local env = CfUtils.GetLuaScr(self.TitleGroup.gameObject, PVPArenaReplayTitleGroupPath)
    if isNull(env) then return end
    env:RefreshUI(oneMatchChartData)
end

function PVPArenaReplayDialog:RefreshTeamGroups(teams)
    local teamNumbers = pvpArenaComponent:GetTeamNumbers()
    for i = 1, teamNumbers do
        local teamData = teams[2 * i - 1]
        local LeftItem = self[string.format("LeftItem%s", i)]
        self:RefreshOneTeamGroup(LeftItem.gameObject, teamData)

        teamData = teams[2 * i]
        local RightItem = self[string.format("RightItem%s", i)]
        self:RefreshOneTeamGroup(RightItem.gameObject, teamData)
    end
end

function PVPArenaReplayDialog:RefreshOneTeamGroup(gameObject, data)
    if data == nil then
        return
    end
    ---@type PVPArenaReplayTeamInfoNode
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaReplayTeamInfoNodePath)
    if isNull(env) then return end
    env:RefreshUI(data)
end

